package com.example.rokidkeyboardbridge;
import org.json.*;
public class ConversationFlowTest{static int checks;static void ok(boolean b){checks++;if(!b)throw new AssertionError("check "+checks);}public static void main(String[] args)throws Exception{
 ok(VoiceRevisionPolicy.correction("電線じゃなく沿線だよ"));ok(VoiceRevisionPolicy.correction("いや、そうじゃなくて沿線さんの話"));ok(!VoiceRevisionPolicy.correction("いやー、いい天気だね"));ok(VoiceRevisionPolicy.carry("月額を計算して","時給は4101円じゃなく4000円").contains("月額を計算して"));ok(VoiceRevisionPolicy.carry("同じ","同じ").equals("同じ"));
 ok(ConversationFollowupPolicy.referencesPrevious("年間では？"));ok(ConversationFollowupPolicy.referencesPrevious("それなら？"));
 String speech=SpeechCitationPolicy.forSpeech("回答です。 [[LISTEN:1:DEFAULT]] https://example.com/abcdefghijklmnopqrstuvwxyz");ok(!speech.contains("LISTEN"));ok(!speech.contains("https"));ok(speech.contains("回答です"));ok(SpeechCitationPolicy.forSpeech("回答です。\n出典：example.com").equals("回答です。"));String longText="説明です。".repeat(200);ok(SpeechCitationPolicy.forRequest("全文を読んで",longText).equals(longText));ok(SpeechCitationPolicy.forRequest("要点だけ",longText).length()<650);ok(SpeechCitationPolicy.forRequest("要点だけ",longText).contains("続きは画面"));
 long now=100000000;JSONObject old=new JSONObject().put("at",now-1000).put("imageCount",1).put("question","前").put("answer","古い読み取り"),recent=new JSONObject().put("at",now).put("imageCount",1).put("question","今").put("answer","新しい読み取り");JSONArray rows=ImageReferenceHistory.add(new JSONArray().put(old),recent,now);ok(rows.length()==2);ok(ImageReferenceHistory.previous(rows,now,now).getString("question").equals("前"));ok(ImageReferenceHistory.previous(rows,now,now+ImageReferencePolicy.TTL_MS)==null);ok(ImageReferencePolicy.followup("2枚目には何と書いてある？",now,now));ok(ImageReferencePolicy.followup("前の写真について",now,now));JSONObject before=ImageReferenceSummary.view(old,now),selected=ImageReferenceSummary.view(new JSONObject(old.toString()).put("selectedAt",now),now);ok(!before.getString("key").equals(selected.getString("key")));ok(selected.getLong("at")==now-1000);
 JSONObject journey=new JSONObject().put("fetchedAt",now).put("transitStops",new JSONArray().put(new JSONObject())).put("currentLeg",new JSONObject().put("travelMode","TRANSIT"));JSONObject hud=JourneyHud.withTransitHealth(new JSONObject(),journey);ok(hud.getString("detail").contains("残駅数未取得"));ok(hud.getString("detail").contains("降車時刻：経路API未提供"));journey.getJSONObject("currentLeg").put("remainingStopCount",3).put("arrivalTime","2026-10-20T12:00:00Z");hud=JourneyHud.withTransitHealth(new JSONObject(),journey);ok(hud.getString("detail").contains("残り3駅"));ok(!hud.getString("detail").contains("残駅数未取得"));System.out.println("PASS "+checks+" voice revision / follow-up / speech / image selection / transit missing-data checks; no API calls");}}
